"""Six-frame blocking board using real existing assets; missing poses are explicitly not fabricated."""
from pathlib import Path
import base64,json
from playwright.sync_api import sync_playwright
root=Path(__file__).resolve().parents[1];integration=root.parent/'ruby-village';out=root/'docs/chapter-1-rc/ui-map/prologue'
def data(path):return 'data:image/png;base64,'+base64.b64encode(path.read_bytes()).decode()
gate=data(integration/'art/chapter-1-v9/candidates/gate-v3-base.png');ruta=data(integration/'public/assets/characters-v1/ruta-idle-pilot.png');garden=data(root/'public/assets/chapter-1/v6/02-orchard.png')
frames=[('Утро во дворе','Это Рута. Она живёт в Рубиновой деревне, где друзья всегда помогают друг другу','Нет basket-hold и корзины; idle — только blocking.',True),('Яблоки Кролику','Кролик сегодня печёт пирог. Я обещала принести ему яблоки!','Нет basket-hold, корзины и intact-road слоя.',True),('Кролик готовит пирог','Кролик живёт за калиткой, в яблоневом саду. Он уже ждёт Руту','Сад v6 — reference. Кролик/миска/ложка отсутствуют, SVG не подставлен.',False),('Дорога пропала','Ой… Вчера здесь была дорожка! А теперь камни лежат в стороне','Нет surprised, drawn loose stones и корзины.',True),('Рута у камня','Попробую сложить их обратно. Тогда смогу дойти до Кролика','Crouch отсутствует: стоящая Рута не выдана за приседание.',False),('К калитке','Начнём с дорожки до калитки. Поможешь мне?','Idle на native start anchor; без сетки/лотка. Финальная камера требует #46.',True)]
html='<meta charset=utf-8><style>*{box-sizing:border-box}body{margin:0;padding:18px;background:#f0e5d0;color:#473323;font:15px Georgia}h1{font-size:24px}main{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.card{background:#fff6e4;border:1px solid #b59b77;border-radius:8px;overflow:hidden}.stage{position:relative;aspect-ratio:1672/941}.bg{width:100%;height:100%}.ruta{position:absolute;left:27.945%;top:31.055%;width:3.887%;height:14.453%}h2,p{margin:9px 11px}h2{font-size:18px}.gap{font:13px system-ui;background:#f4dfb4;padding:8px;border-radius:4px}small{font:13px system-ui}</style><h1>Пролог · шесть кадров блокинга, не финальная постановка</h1><p>Приняты внешность Руты и стиль двора. Ниже реальные доступные assets; недостающие позы/предметы не имитируются.</p><main>'
for i,(title,text,gap,show) in enumerate(frames):
 html+=f'<article class=card><div class=stage><img class=bg src="{garden if i==2 else gate}">'+(f'<img class=ruta src="{ruta}">' if show else '')+f'</div><h2>{i+1}. {title}</h2><p>{text}</p><p class=gap>{gap}</p></article>'
html+='</main><p><small>Сцена двора native 1672×941, start=(503.7307,426.5); Ruta 463×970, native foot=(245,958), scene height136. В позах 1/2/4 idle показан только как blocking. Кадр6 — точная start-foot привязка, камера не увеличивается ради действия. Не является доказательством finished #47.</small></p>'
with sync_playwright() as p:
 browser=p.chromium.launch();page=browser.new_page(viewport={'width':1600,'height':1100});page.set_content(html);page.locator('img').evaluate_all('(images)=>Promise.all(images.map(i=>i.decode()))');page.screenshot(path=str(out/'six-frame-resource-blocking.jpg'),full_page=True,quality=90);browser.close()
(out/'blocking-sources.json').write_text(json.dumps({'scope':'six-frame resource blocking, not finished art or production','gate':'art/chapter-1-v9/candidates/gate-v3-base.png','gateSourceCommit':'1d0dad5','ruta':'public/assets/characters-v1/ruta-idle-pilot.png','rutaAppearance':'accepted 2026-10-17, pose pending','garden':'public/assets/chapter-1/v6/02-orchard.png; reference only','camera':{'nativeSize':[1672,941],'start':[503.73066958946424,426.5]},'missingPoses':['basket-hold','surprised','crouch','rabbit-baking']},indent=2)+'\n')
print('Six-frame actual resource blocking board saved; not finished #47')
